/**
 * How long a lab level takes, and how long is left on one in progress.
 */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    getStaticLabWorkingLevelDurationHours, estimateLabLevelRemainingSeconds
 * depends    src/mechanics/effective-paths/lab-costs
 * used by    src/calculators/specs.generated, src/save/labs/index, src/save/labs/read
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { labDurationDaysToReachLevel } from '../../mechanics/effective-paths/lab-costs'

const HOURS_PER_DAY = 24

/**
 * How long the level after `completedLevel` takes, in hours.
 *
 * This is `labDurationDaysToReachLevel` asked for the next level, and nothing else. It used to be a
 * second copy of that formula with one difference: it left the Labs Speed research out of the Labs
 * Speed lab's own time, after a wiki sentence saying the research "does not" shorten its own
 * levels. The game disagrees. On a real v29.2.1 export, Labs Speed 53 -> 54 was due in 9.8107 days
 * where the catalog's unmodified time is 20.513 -- exactly 1 + 0.02 x 53, times one +1.5% relic --
 * and this function reported it at more than twice its real length.
 *
 * `labSpeedRelicPct` is a fraction, 0.015 for +1.5%, as it is everywhere else lab speed is read.
 */
export function getStaticLabWorkingLevelDurationHours(
  displayName: string | null | undefined,
  completedLevel: number,
  labSpeedLevel = 0,
  labSpeedRelicPct = 0,
): number | null {
  if (!displayName) return null

  // No entry for the next level means the lab is maxed, so there is nothing left to time.
  const workingLevel = Math.max(1, Math.floor(Number(completedLevel) || 0) + 1)
  const days = labDurationDaysToReachLevel(displayName, workingLevel, {
    labSpeedLabLevel: Math.max(0, Number(labSpeedLevel) || 0),
    labSpeedRelicPct: Math.max(0, Number(labSpeedRelicPct) || 0),
  })
  if (days === null || !Number.isFinite(days) || days <= 0) return null
  return days * HOURS_PER_DAY
}

export function estimateLabLevelRemainingSeconds(
  displayName: string | null | undefined,
  completedLevel: number,
  percentComplete: number | null | undefined,
  labSpeedLevel = 0,
  labSpeedRelicPct = 0,
): number | null {
  const durationHours = getStaticLabWorkingLevelDurationHours(
    displayName, completedLevel, labSpeedLevel, labSpeedRelicPct,
  )
  if (durationHours == null) return null

  const progress = Math.max(0, Math.min(1, Number(percentComplete) || 0))
  const remainingHours = durationHours * (1 - progress)
  return Math.max(0, Math.round(remainingHours * 3600))
}
